<script>document.addEventListener('DOMContentLoaded',function(){function setup(campusId,classId,sectionId,currentSection){const campus=document.getElementById(campusId),cls=document.getElementById(classId),section=document.getElementById(sectionId);const all=[...cls.options].slice(1).map(o=>({value:o.value,text:o.textContent,branch:o.dataset.branch||'',sections:o.dataset.sections||'[]',selected:o.selected}));function renderClasses(){const branch=campus.value,current=cls.value;cls.innerHTML='<option value="">'+(classId==='reportClass'?'Select Class':'All Classes')+'</option>';all.filter(o=>!branch||!o.branch||o.branch===branch).forEach(o=>{const x=document.createElement('option');Object.assign(x,{value:o.value,textContent:o.text});x.dataset.branch=o.branch;x.dataset.sections=o.sections;if(o.value===current)x.selected=true;cls.appendChild(x)});if(![...cls.options].some(o=>o.value===current))cls.value='';renderSections()}function renderSections(){const o=cls.options[cls.selectedIndex];let list=[];try{list=JSON.parse(o?.dataset?.sections||'[]')}catch(e){}const wanted=section.value||currentSection||'';section.innerHTML='<option value="">All Sections</option>';list.forEach(v=>{const x=document.createElement('option');x.value=v;x.textContent=v;if(v===wanted)x.selected=true;section.appendChild(x)});}campus.addEventListener('change',renderClasses);cls.addEventListener('change',renderSections);renderClasses()}setup('studentFilterCampus','studentFilterClass','studentFilterSection',@json(request('section')));setup('reportCampus','reportClass','reportSection','');});</script>
